claims.text:
.card{background:#fff;border:1px solid #e3e6ea;border-radius:10px;padding:14px 16px;margin:12px 0;box-shadow:0 1px 2px rgba(16,24,40,.04)}
.card table{border-collapse:collapse;width:100%;font-size:13px;margin:8px 0}
.card th{background:#f5f7fa;text-align:left;padding:6px 8px;border:1px solid #e3e6ea;font-weight:600}
.card td{padding:6px 8px;border:1px solid #eef0f3;vertical-align:top}
.mut{color:#6b7280;font-size:12px}
b{color:#0f172a}
.obslist{display:grid;gap:10px}
.obs{background:#fff;border:1px solid #e3e6ea;border-left:4px solid #2563eb;border-radius:8px;padding:12px 14px}
.obs-head{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;margin-bottom:6px}
.obs-nm{font-weight:700;font-size:15px}
.obs-pos{background:#eff6ff;color:#1d4ed8;border-radius:999px;padding:2px 10px;font-size:12px}
.obs-rec{margin:0;font-size:13px;line-height:1.75;color:#1f2937}
.neg{color:#b91c1c}
.pos{color:#047857}
